import { Effect } from "effect"
import { copyFile, mkdtemp, rm, writeFile } from "node:fs/promises"
import { tmpdir } from "node:os"
import { join } from "node:path"

export interface BuildManifest {
  readonly version: string
  readonly assets: ReadonlyArray<string>
}

export const writeManifest = (
  destination: string,
  manifest: BuildManifest
) =>
  Effect.scoped(
    Effect.gen(function*() {
      const workspace = yield* Effect.acquireRelease(
        Effect.tryPromise({
          try: () => mkdtemp(join(tmpdir(), "build-manifest-")),
          catch: (cause) => new Error("Cannot create manifest workspace", { cause })
        }),
        (directory) =>
          Effect.tryPromise({
            try: () => rm(directory, { recursive: true, force: true }),
            catch: (cause) => new Error("Cannot remove manifest workspace", { cause })
          }).pipe(Effect.orDie)
      )

      const stagedPath = join(workspace, "manifest.json")
      yield* Effect.tryPromise({
        try: () => writeFile(stagedPath, JSON.stringify(manifest, null, 2), "utf8"),
        catch: (cause) => new Error("Cannot stage build manifest", { cause })
      })

      yield* Effect.tryPromise({
        try: () => copyFile(stagedPath, destination),
        catch: (cause) => new Error("Cannot publish build manifest", { cause })
      })

      return destination
    })
  )

